import React, { useState } from 'react';
import FileUploader from '../components/FileUploader';
import Result from '../components/Result';
import axios from 'axios';

const JAVA_URL = 'http://localhost:8080/api';

const QuizPage = () => {
    const [result, setResult] = useState(null);
    const [error, setError] = useState(null);
    const [isLoading, setIsLoading] = useState(false);

    const handleFileUpload = async (file) => {
    if (!file) {
        setError("Veuillez sélectionner un fichier valide.");
        return;
    }

    setIsLoading(true);
    setError(null);
    setResult(null);

    try {
        const text = await file.text();
        
        // Créez l'objet à envoyer
        const quizData = {
            content: text
        };

        const response = await axios.post(`${JAVA_URL}/quizzes/generate`, quizData, {
            headers: {
                'Content-Type': 'application/json'
            }
        });

        console.log('Réponse du serveur:', response.data);
        console.log("Texte à envoyer au backend :", text);

        
        if (response.data) {
            setResult(response.data);
        }

    } catch (error) {
        console.error('Erreur détaillée:', error.response || error);
        setError("Échec de la génération du quiz");
    } finally {
        setIsLoading(false);
    }
};

    return (
        <div className="quiz-page">
            <h1>Générer un Quiz</h1>

            <FileUploader
                onUpload={handleFileUpload}
                disabled={isLoading}
                accept=".txt"
            />

            {isLoading && (
                <div className="loading-container">
                    <p className="loading-message">Génération du quiz en cours...</p>
                </div>
            )}

            {error && <p className="error-message">{error}</p>}
            {result && <Result data={result} />}
        </div>
    );
};

export default QuizPage;
